/*
 * m4_footprint.c - static memory footprint of an 8-channel eeg_filter instance (build-only).
 *
 * Module : eeg_filter (task #17)
 * Author : Tran Khoa Vu (tran-khoa-vu-k68), with Claude Code
 * Date   : 2026-11-09
 *
 * Compiled by the flow with arm-none-eabi-gcc for Cortex-M4F (-mfpu=fpv4-sp-d16, hard float)
 * and measured with arm-none-eabi-size; it is never linked or run. It shows the flash/RAM a
 * firmware pays for coefficients, per-channel state and instances. The coefficient header is
 * the one generated by the flow (EEG_COEFF_HEADER, EEG_CHAIN_NUM_STAGES and EEG_CHAIN_COEFFS
 * are set on the compiler command line).
 */
#include "eeg_filter.h"

#include EEG_COEFF_HEADER

#define EEG_NUM_CHANNELS 8U

static float32_t g_state[EEG_NUM_CHANNELS][EEG_FILTER_STATE_LEN(EEG_CHAIN_NUM_STAGES)];
static eeg_filter_t g_filter[EEG_NUM_CHANNELS];

void eeg_footprint_init(void);
void eeg_footprint_process(const int32_t *codes, float32_t *out, uint32_t n);

void eeg_footprint_init(void)
{
    uint32_t ch;
    for (ch = 0U; ch < EEG_NUM_CHANNELS; ch++) {
        eeg_filter_init(&g_filter[ch], (uint8_t)EEG_CHAIN_NUM_STAGES, EEG_CHAIN_COEFFS,
                        g_state[ch], EEG_ADC_LSB_UV);
    }
}

/* codes/out are channel-major blocks of n samples per channel. */
void eeg_footprint_process(const int32_t *codes, float32_t *out, uint32_t n)
{
    uint32_t ch;
    for (ch = 0U; ch < EEG_NUM_CHANNELS; ch++) {
        eeg_filter_process_codes(&g_filter[ch], codes + ch * n, out + ch * n, n);
    }
}
